    56→public class JavaScriptAggregatorFactory extends AggregatorFactory
    57→{
    58→  private final String name;
    59→  private final List<String> fieldNames;
    60→  private final String fnAggregate;
    61→  private final String fnReset;
    62→  private final String fnCombine;
    63→  private final JavaScriptConfig config;
