    72→   */
    73→  private volatile JavaScriptAggregator.@MonotonicNonNull ScriptAggregator compiledScript;
    74→
    75→  @JsonCreator
    76→  public JavaScriptAggregatorFactory(
    77→      @JsonProperty("name") String name,
    78→      @JsonProperty("fieldNames") final List<String> fieldNames,
    79→      @JsonProperty("fnAggregate") final String fnAggregate,
    80→      @JsonProperty("fnReset") final String fnReset,
    81→      @JsonProperty("fnCombine") final String fnCombine,
    82→      @JacksonInject JavaScriptConfig config
    83→  )
    84→  {
    85→    Preconditions.checkNotNull(name, "Must have a valid, non-null aggregator name");
    86→    Preconditions.checkNotNull(fieldNames, "Must have a valid, non-null fieldNames");
    87→    Preconditions.checkNotNull(fnAggregate, "Must have a valid, non-null fnAggregate");
