    99→
   100→  @Override
   101→  public Aggregator factorize(final ColumnSelectorFactory columnFactory)
   102→  {
   103→    JavaScriptAggregator.ScriptAggregator compiledScript = getCompiledScript();
   104→    return new JavaScriptAggregator(
   105→        fieldNames.stream().map(columnFactory::makeColumnValueSelector).collect(Collectors.toList()),
   106→        compiledScript
   107→    );
   108→  }
   109→
   110→  @Override
   111→  public BufferAggregator factorizeBuffered(final ColumnSelectorFactory columnSelectorFactory)
   112→  {
   113→    JavaScriptAggregator.ScriptAggregator compiledScript = getCompiledScript();
   114→    return new JavaScriptBufferAggregator(
   115→        fieldNames.stream().map(columnSelectorFactory::makeColumnValueSelector).collect(Collectors.toList()),
   116→        compiledScript
   117→    );
   118→  }
   119→
   120→  @Override
   121→  public Comparator getComparator()
   122→  {
   123→    return DoubleSumAggregator.COMPARATOR;
   124→  }
   125→
   126→  @Override
   127→  public Object combine(Object lhs, Object rhs)
   128→  {
   129→    JavaScriptAggregator.ScriptAggregator compiledScript = getCompiledScript();
   130→    return compiledScript.combine(((Number) lhs).doubleValue(), ((Number) rhs).doubleValue());
   131→  }
   132→
   133→  @Override
   134→  public AggregateCombiner makeAggregateCombiner()
   135→  {
   136→    return new DoubleAggregateCombiner()
   137→    {
   138→      private double combined;
   139→
   140→      @Override
   141→      public void reset(ColumnValueSelector selector)
   142→      {
   143→        combined = selector.getDouble();
   144→      }
   145→
   146→      @Override
   147→      public void fold(ColumnValueSelector selector)
   148→      {
   149→        JavaScriptAggregator.ScriptAggregator compiledScript = getCompiledScript();
   150→        combined = compiledScript.combine(combined, selector.getDouble());
   151→      }
   152→
   153→      @Override
   154→      public double getDouble()
   155→      {
   156→        return combined;
   157→      }
   158→    };
   159→  }
   160→
   161→  @Override
   162→  public AggregatorFactory getCombiningFactory()
   163→  {
   164→    return new JavaScriptAggregatorFactory(name, Collections.singletonList(name), fnCombine, fnReset, fnCombine, config);
   165→  }
   166→
   167→  @Override
   168→  public AggregatorFactory getMergingFactory(AggregatorFactory other) throws AggregatorFactoryNotMergeableException
   169→  {
   170→    if (other.getName().equals(this.getName()) && other.getClass() == this.getClass()) {
   171→      JavaScriptAggregatorFactory castedOther = (JavaScriptAggregatorFactory) other;
   172→      if (this.fnCombine.equals(castedOther.fnCombine) && this.fnReset.equals(castedOther.fnReset)) {
   173→        return getCombiningFactory();
   174→      }
