   214→  @JsonProperty
   215→  @Override
   216→  public String getName()
   217→  {
   218→    return name;
   219→  }
   220→
   221→  @JsonProperty
   222→  public List<String> getFieldNames()
   223→  {
   224→    return fieldNames;
   225→  }
   226→
   227→  @JsonProperty
   228→  public String getFnAggregate()
   229→  {
   230→    return fnAggregate;
   231→  }
   232→
   233→  @JsonProperty
   234→  public String getFnReset()
   235→  {
   236→    return fnReset;
   237→  }
   238→
   239→  @JsonProperty
   240→  public String getFnCombine()
   241→  {
   242→    return fnCombine;
   243→  }
   244→
   245→  @Override
   246→  public List<String> requiredFields()
   247→  {
   248→    return fieldNames;
   249→  }
