   251→  @Override
   252→  public byte[] getCacheKey()
   253→  {
   254→    try {
   255→      MessageDigest md = MessageDigest.getInstance("SHA-1");
   256→      byte[] fieldNameBytes = StringUtils.toUtf8(Joiner.on(",").join(fieldNames));
   257→      byte[] sha1 = md.digest(StringUtils.toUtf8(fnAggregate + fnReset + fnCombine));
   258→
   259→      return ByteBuffer.allocate(1 + fieldNameBytes.length + sha1.length)
   260→                       .put(AggregatorUtil.JS_CACHE_TYPE_ID)
   261→                       .put(fieldNameBytes)
   262→                       .put(sha1)
   263→                       .array();
   264→    }
   265→    catch (NoSuchAlgorithmException e) {
   266→      throw new RuntimeException("Unable to get SHA1 digest instance", e);
   267→    }
   268→  }
   269→
